    "PaleeWeb.ExecutionController.record_interactions": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Execution ID */
                id: string;
            };
            cookie?: never;
        };
        /** @description Interaction events */
        requestBody?: {
            content: {
                "application/json": {
                    events: {
                        /** Format: uuid */
                        client_event_id: string;
                        /** @enum {string} */
                        kind: "cast_mode_toggled" | "check_off_undone" | "cues_toggled" | "finish_wizard_abandoned" | "finish_wizard_opened" | "finish_wizard_saved" | "first_segment_started" | "pause" | "ready_screen_shown" | "resume" | "round_decremented" | "round_incremented" | "rounds_adjusted" | "segment_restarted" | "segment_skipped" | "time_adjusted" | "workout_launched";
                        /** @description Typed facts allowed for the interaction kind (see ADR-123). No free text; keys not allowed for the kind reject the batch. */
                        metadata?: {
                            countdown_seconds?: number;
                            /** @enum {string} */
                            cue_channel?: "sound" | "voice" | "vibration";
                            delta_rounds?: number;
                            delta_seconds?: number;
                            duration_ms?: number;
                            elapsed_ms?: number;
                            enabled?: boolean;
                            format?: string;
                            /** @enum {string} */
                            orientation?: "portrait" | "landscape";
                            remaining_ms?: number;
                            round_count?: number;
                            scored_section_count?: number;
                            section_id?: string;
                            segment_index?: number;
                            step?: number;
                            /** @enum {string} */
                            surface?: "pause_sheet" | "primary_action" | "header" | "gesture" | "keyboard" | "snackbar" | "ready_screen" | "finish_wizard" | "cast_display" | "lock_screen";
                        };
                        /** Format: date-time */
                        occurred_at: string;
                    }[];
                };
            };
        };
        responses: {
            /** @description Batch accepted */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        accepted: number;
                        duplicates: number;
                    };
                };
            };
            /** @description Execution not found */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": Record<string, never>;
                };
            };
            /** @description Invalid interaction batch */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        code: "invalid_execution_interactions";
                        errors: {
                            index: number;
                            reason: string;
                        }[];
                    };
                };
            };
        };
    };
