                    cohost_slugs?: string[];
                    /**
                     * Format: uuid
                     * @description A ready box photo upload
                     */
                    cover_media_id?: string | null;
                    currency?: string;
                    description?: string | null;
                    /** Format: date-time */
                    ends_at: string;
