    "PaleeWeb.WalletController.devices": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Connected devices */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        calendar: {
                            download_url?: string;
                            help?: {
                                [key: string]: string;
                            };
                            https_url: string;
                            webcal_url: string;
                        };
                        integrations: {
                            backfill_day_options?: number[];
                            /** @enum {string} */
                            capability?: "available" | "not_configured";
                            configured?: boolean;
                            connection?: (({
                                /** @enum {integer} */
                                backfill_days: 0 | 30 | 90;
                                /** @description «Εισαγωγή… 40%» while the history import runs */
                                backfill_progress?: number | null;
                                /** @enum {string} */
                                backfill_status: "none" | "running" | "done" | "failed";
                                /** Format: date-time */
                                connected_at?: string | null;
                                last_error?: string | null;
                                /** Format: date-time */
                                last_synced_at?: string | null;
                                needs_reconnect: boolean;
                                /** @enum {string} */
                                status: "active" | "error";
                                /**
                                 * DeviceSyncPrefs
                                 * @description What is brought in: workouts (Ημερολόγιο), sleep (Ευεξία), weight (Σώμα), resting heart rate (Πρόοδος)
                                 */
                                sync_prefs: {
                                    activities?: boolean;
                                    resting_hr?: boolean;
                                    sleep?: boolean;
                                    /** @description Phones only (ADR-172) */
                                    steps?: boolean;
                                    weight?: boolean;
                                };
                            } | null) | ({
                                /** Format: date-time */
                                connected_at?: string | null;
                                /** Format: date-time */
                                last_synced_at?: string | null;
                                /**
                                 * Format: date-time
                                 * @description Where the app starts reading at its next sync: 30 days back at first, then two days before the last sync
                                 */
                                read_from?: string | null;
                                /** @enum {string} */
                                status: "active";
                                /**
                                 * PhoneHealthSyncPrefs
                                 * @description What the phone brings in: workouts (Ημερολόγιο), sleep (Ευεξία), weight (Σώμα), resting heart rate and steps (Πρόοδος)
                                 */
                                sync_prefs: {
                                    activities?: boolean;
                                    resting_hr?: boolean;
                                    sleep?: boolean;
                                    steps?: boolean;
                                    weight?: boolean;
                                };
                            } | null)) | null;
                            history_days?: number;
                            /** @enum {string} */
                            provider: "garmin" | "apple_health" | "health_connect";
                            /** @enum {string} */
                            status: "connected" | "disconnected" | "unavailable" | "native_only" | "error";
                            /**
                             * DeviceSyncPrefs
                             * @description What is brought in: workouts (Ημερολόγιο), sleep (Ευεξία), weight (Σώμα), resting heart rate (Πρόοδος)
                             */
                            sync_prefs?: {
                                activities?: boolean;
                                resting_hr?: boolean;
                                sleep?: boolean;
                                /** @description Phones only (ADR-172) */
                                steps?: boolean;
                                weight?: boolean;
                            };
                        }[];
                        wallet: {
                            passes: {
                                active: boolean;
                                /** Format: date-time */
                                added_at: string;
                                box?: {
                                    name?: string | null;
                                    /** Format: uuid */
                                    organization_id?: string;
                                    slug?: string | null;
                                };
                                /** Format: uuid */
                                id: string;
                                /** Format: date-time */
                                last_updated_at?: string;
                                /** @enum {string} */
                                platform: "apple" | "google";
                                /** Format: date-time */
                                revoked_at?: string | null;
                            }[];
                            /** @description Whether this server can issue cards per platform */
                            platforms: {
                                apple?: boolean;
                                google?: boolean;
                            };
                        };
                    };
                };
            };
        };
    };
