    "PaleeWeb.DevicesController.sync": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The Garmin row */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** GarminDeviceRow */
                        garmin: {
                            backfill_day_options?: number[];
                            /** @enum {string} */
                            capability: "available" | "not_configured";
                            configured: boolean;
                            /** GarminConnection */
                            connection?: {
                                /** @enum {integer} */
                                backfill_days: 0 | 30 | 90;
                                /** @description «Εισαγωγή… 40%» while the history import runs */
                                backfill_progress?: number | null;
                                /** @enum {string} */
                                backfill_status: "none" | "running" | "done" | "failed";
                                /** Format: date-time */
                                connected_at?: string | null;
                                last_error?: string | null;
                                /** Format: date-time */
                                last_synced_at?: string | null;
                                needs_reconnect: boolean;
                                /** @enum {string} */
                                status: "active" | "error";
                                /**
                                 * DeviceSyncPrefs
                                 * @description What is brought in: workouts (Ημερολόγιο), sleep (Ευεξία), weight (Σώμα), resting heart rate (Πρόοδος)
                                 */
                                sync_prefs: {
                                    activities?: boolean;
                                    resting_hr?: boolean;
                                    sleep?: boolean;
                                    /** @description Phones only (ADR-172) */
                                    steps?: boolean;
                                    weight?: boolean;
                                };
                            } | null;
                            /** @enum {string} */
                            provider: "garmin";
                            /**
                             * @description `unavailable` is «Σύντομα»: this server has no Garmin credentials
                             * @enum {string}
                             */
                            status: "unavailable" | "disconnected" | "connected" | "error";
                            /**
                             * DeviceSyncPrefs
                             * @description What is brought in: workouts (Ημερολόγιο), sleep (Ευεξία), weight (Σώμα), resting heart rate (Πρόοδος)
                             */
                            sync_prefs: {
                                activities?: boolean;
                                resting_hr?: boolean;
                                sleep?: boolean;
                                /** @description Phones only (ADR-172) */
                                steps?: boolean;
                                weight?: boolean;
                            };
                        };
                    };
                };
            };
            /** @description Asked too recently */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
        };
    };
