    "PaleeWeb.AccountTrainingController.vault": {
        parameters: {
            query?: {
                /** @description Comma-separated workout types */
                disciplines?: string;
                /** @description A benchmark slug such as `fran` */
                benchmark?: string;
                /** @description An exercise name (matched by substring) */
                exercise?: string;
                /** @description Comma-separated provider ids, `freeform`, `device` (all when absent) */
                sources?: string;
                date_from?: string;
                date_to?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Vault */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        active_filter_count: number;
                        filter: {
                            [key: string]: unknown;
                        };
                        groups: {
                            attempt_count: number;
                            attempts: {
                                /** Format: date-time */
                                at: string;
                                duration_seconds?: number | null;
                                /** Format: uuid */
                                id: string;
                                /** @enum {string} */
                                kind: "execution" | "training_log";
                                /**
                                 * Format: uuid
                                 * @description Workout to repeat, when the attempt has one.
                                 */
                                master_workout_id: string | null;
                                /** Format: date */
                                on?: string;
                                /**
                                 * Format: uuid
                                 * @description Provider the attempt belongs to (null for a freeform or device entry); «Ξανά» switches to it first.
                                 */
                                organization_id: string | null;
                                scale_level_slug?: string | null;
                                scores?: {
                                    section_id?: string | null;
                                    section_name?: string | null;
                                    unit?: string | null;
                                    value?: unknown;
                                }[];
                                /**
                                 * EntrySource
                                 * @description Where an entry came from; `former` once the membership there ended.
                                 */
                                source: {
                                    former: boolean;
                                    /** @enum {string} */
                                    kind: "organization" | "freeform" | "device";
                                    name: string | null;
                                    /** Format: uuid */
                                    organization_id: string | null;
                                };
                                title?: string | null;
                                type?: string | null;
                                tz?: string | null;
                            }[];
                            benchmark?: string | null;
                            identity: string;
                            /** Format: date-time */
                            last_at: string;
                            sources: {
                                former: boolean;
                                /** @enum {string} */
                                kind: "organization" | "freeform" | "device";
                                name: string | null;
                                /** Format: uuid */
                                organization_id: string | null;
                            }[];
                            title: string | null;
                            workout_type?: string | null;
                        }[];
                    };
                };
            };
        };
    };
