    "PaleeWeb.AdminCheckInController.check_in_member": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                user_id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** Format: uuid */
                    booking_id?: string;
                    /** Format: uuid */
                    location_id?: string;
                    /** @enum {string} */
                    method?: "member_qr" | "wallet" | "desk_search";
                    /** @description «Check-in παρ' όλα αυτά»: only when the owner allows desk overrides */
                    override?: boolean;
                };
            };
        };
        responses: {
            /** @description Checked in */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string|null} */
                        already_checked_in?: null | "class" | "open_gym";
                        /** @description Bookings in the window */
                        bookings?: {
                            duration_minutes?: number | null;
                            /** Format: uuid */
                            id: string;
                            /** @enum {string|null} */
                            kind?: null | "member" | "guest" | "trial";
                            /** Format: uuid */
                            location_id?: string | null;
                            name?: string | null;
                            /** Format: uuid */
                            scheduled_class_id: string;
                            /** Format: date-time */
                            starts_at: string;
                        }[];
                        can_auto_check_in: boolean;
                        /** CheckInRecord */
                        checked_in?: {
                            /** Format: date-time */
                            at?: string | null;
                            booking?: {
                                duration_minutes?: number | null;
                                /** Format: uuid */
                                id: string;
                                /** @enum {string|null} */
                                kind?: null | "member" | "guest" | "trial";
                                /** Format: uuid */
                                location_id?: string | null;
                                name?: string | null;
                                /** Format: uuid */
                                scheduled_class_id: string;
                                /** Format: date-time */
                                starts_at: string;
                            } | null;
                            /** Format: uuid */
                            id?: string | null;
                            /** @enum {string} */
                            kind: "class" | "open_gym";
                            /** @enum {string|null} */
                            method?: "door_qr" | "door_poster" | "door_nfc" | "geofence" | "member_qr" | "wallet" | "desk_search" | "self" | null;
                            override?: boolean;
                        } | null;
                        /** @enum {string} */
                        decision: "class" | "choose" | "already_checked_in" | "open_gym" | "nothing" | "booking_not_in_window";
                        member: {
                            avatar_url?: string | null;
                            display_name?: string | null;
                            /** Format: uuid */
                            id: string;
                            nickname?: string | null;
                        };
                        /** @enum {string} */
                        method?: "member_qr" | "wallet" | "desk_search";
                        /** Format: uuid */
                        organization_id?: string;
                        override_allowed: boolean;
                        /**
                         * CheckInPackage
                         * @description What is left on the member's package; null when the box keeps no package for them
                         */
                        package?: {
                            /** @description null = unlimited or not part of the package */
                            class_visits_left?: number | null;
                            /** Format: date */
                            expires_on?: string | null;
                            /** Format: date */
                            frozen_until?: string | null;
                            name?: string | null;
                            /** @description null = unlimited or not part of the package */
                            open_gym_visits_left?: number | null;
                            status?: string | null;
                            unlimited?: boolean;
                        } | null;
                        problems: ("frozen" | "package_expired" | "unpaid" | "no_spots" | "nothing_to_check_in")[];
                        warnings?: "payment_due"[];
                    };
                };
            };
            /** @description The owner doesn't allow desk overrides */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
            /** @description Problems with the package, or a booking to pick */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
        };
    };
