    "PaleeWeb.AdminSettingsController.show": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Admin settings */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        finance: {
                            /** @enum {string} */
                            document_mode: "invoice" | "receipt";
                            /** Format: uuid */
                            id?: string | null;
                            /** Format: date-time */
                            inserted_at?: string | null;
                            package_modules?: string[];
                            payment_reminder_interval_days: number;
                            /** @description Days before a subscription ends to remind the member (0 = no reminder) */
                            subscription_expiry_reminder_days: number;
                            /** @description Slack days after a subscription ends or an invoice falls overdue before the member loses access */
                            subscription_grace_days: number;
                            /** Format: date-time */
                            updated_at?: string | null;
                        };
                        gamification: {
                            /** Format: uuid */
                            id?: string | null;
                            /** Format: date-time */
                            inserted_at?: string | null;
                            leaderboard_enabled: boolean;
                            /** @description Day of the month the shields renew; null renews each member's on their sign-up day */
                            streak_shield_reset_day?: number | null;
                            /** @description Streak shields each member gets at every renewal (0 turns shields off) */
                            streak_shields: number;
                            /** Format: date-time */
                            updated_at?: string | null;
                        };
                        /** @description ADR-162: how members see this organization: a gym or an independent coach. Only the owner may change it. */
                        provider: {
                            editable: boolean;
                            /** @enum {string} */
                            kind: "gym" | "coach" | "organiser";
                        };
                        scheduling: {
                            default_auto_approve: boolean;
                            /** @description Minutes a pending booking request waits for staff approval before it is cancelled; null waits until the class starts */
                            default_booking_timeout_minutes: number | null;
                            default_booking_window_days?: number | null;
                            /** @description Minutes before the class after which a withdrawal still uses the visit, when the package sets none; null = no cutoff */
                            default_cancellation_cutoff_minutes?: number | null;
                            default_capacity: number;
                            /** Format: uuid */
                            id?: string | null;
                            /** Format: date-time */
                            inserted_at?: string | null;
                            /** Format: date-time */
                            updated_at?: string | null;
                        };
                        /** @description ADR-176: the gym's IANA time zone. `source` is confirmed (an admin set it), inferred (guessed from a staff device) or null (unknown; `timezone` is the default). */
                        time_zone?: {
                            confirmed: boolean;
                            /** @enum {string|null} */
                            source: "confirmed" | "inferred" | null;
                            timezone: string;
                        };
                        /** @description ADR-163: workout-authoring defaults */
                        workouts: {
                            /** @description ADR-180: whether coaches may use the WOD assistant; off, workouts are written in text sections with a timer each */
                            wod_assistant_enabled: boolean;
                            /** @description ADR-163: starting value of «Εμφάνιση στόχων στα μέλη» for a workout without goals of its own */
                            wod_goals_visible_by_default: boolean;
                        };
                    };
                };
            };
        };
    };
