    "PaleeWeb.AdminWorkoutFreeTextController.analyze": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    locale?: string;
                    text: string;
                };
            };
        };
        responses: {
            /** @description Analysis */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        issues: {
                            /** @description The words of the coach's text the issue is about, exactly as written; the editor marks them in place (nil: the panel only) */
                            anchor?: string | null;
                            /** @description assistant | text_correction | assumption (severity info: a value the assistant inferred; Keep or Reject) | missing_title | missing_type | missing_section_name | missing_exercise_name | too_short | invalid_value | invalid_timer | unknown_format */
                            code: string;
                            current_value?: unknown;
                            id: string;
                            /** @description For text_correction: spelling | unit | number | abbreviation | format | ambiguity */
                            kind?: string | null;
                            message?: string | null;
                            params: {
                                [key: string]: unknown;
                            };
                            /** @description Canonical field path, or "text" for a text-only correction */
                            path: string;
                            required: boolean;
                            /** @enum {string} */
                            severity: "error" | "warning" | "info";
                            suggestion?: {
                                label?: string | null;
                                text_edit?: {
                                    find: string;
                                    replace: string;
                                } | null;
                                /** @description Canonical value for the issue path */
                                value?: unknown;
                            } | null;
                        }[];
                        /**
                         * Format: uuid
                         * @description Groups the model calls of this analysis in the gym's AI usage records (ADR-152)
                         */
                        operation_id?: string;
                        /** @description How much the parser answer had to be repaired against the contract */
                        quality?: {
                            corrections?: number;
                            remaining_violations?: number;
                            repair_attempts?: number;
                            /** @description Whether the structure step (sections and their formats) succeeded before parsing */
                            structure_inferred?: boolean;
                        };
                        suggestions: {
                            field: string;
                            id: string;
                            path: string;
                            reason?: string | null;
                            text_insert?: string | null;
                            value?: unknown;
                        }[];
                        summary: {
                            blocking: number;
                            errors: number;
                            exercises: number;
                            sections: number;
                            warnings: number;
                        };
                        /** @description Canonical workout: title, type, subtitle, description, difficulty, estimated_duration_seconds, equipment, tags and sections[] with name, note, timer_config (its own format per section), scoreable/score_config and exercises[] (interval_assignment for complex_emom / even_odd) */
                        workout: {
                            [key: string]: unknown;
                        };
                    };
                };
            };
            /** @description The gym switched the assistant off */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        code: string;
                        error: string;
                    };
                };
            };
            /** @description Invalid text */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        code: string;
                        error: string;
                    };
                };
            };
            /** @description Assistant unavailable, out of credits or unclear */
            424: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        code: string;
                        error: string;
                    };
                };
            };
            /** @description Assistant not configured */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        code: string;
                        error: string;
                    };
                };
            };
        };
    };
