    "PaleeWeb.ScheduleController.index": {
        parameters: {
            query?: {
                /** @description Calendar window start date */
                start_date?: string;
                /** @description Explicit UTC window start datetime */
                start_at?: string;
                /** @description Explicit UTC window end datetime */
                end_at?: string;
                /** @description Window size in days */
                days?: 1 | 3 | 7 | 30;
                /** @description Optional class type filters */
                class_type_ids?: string[];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Schedule */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        class_types: {
                            [key: string]: unknown;
                        }[];
                        /** @description The coaches of the window's classes. */
                        coaches?: {
                            avatar_url: string | null;
                            /** Format: uuid */
                            id: string;
                            nickname: string;
                        }[];
                        /** @description ADR-230, staff only (empty for others): the WOD of each day in the window, for every class (class_type_id null) or one class type, and every branch (location_id null) or one. */
                        day_workouts: ({
                            /** Format: uuid */
                            class_type_id: string | null;
                            /** Format: uuid */
                            id: string;
                            /** Format: date */
                            local_date: string;
                            /** Format: uuid */
                            location_id: string | null;
                            /** Format: uuid */
                            master_workout_id: string;
                            workout?: {
                                /** Format: uuid */
                                id?: string;
                                title?: string;
                                type?: string | null;
                            } | null;
                        } & {
                            [key: string]: unknown;
                        })[];
                        days: number;
                        /** Format: date */
                        end_date: string;
                        locations?: {
                            accessibility: ("step_free" | "accessible_toilet" | "parking" | "changing_room" | "showers" | "women_area")[];
                            address: string | null;
                            /** Format: date-time */
                            archived_at: string | null;
                            city: string | null;
                            country_code: string | null;
                            /** Format: uuid */
                            id: string;
                            /** Format: date-time */
                            inserted_at?: string;
                            latitude: number | null;
                            longitude: number | null;
                            name: string;
                            neighbourhood: string | null;
                            opening_hours: {
                                closes: string;
                                opens: string;
                                /** @description ISO weekday, Monday = 1 */
                                weekday: number;
                            }[];
                            /** Format: uuid */
                            organization_id?: string;
                            /** Format: date-time */
                            updated_at?: string;
                        }[];
                        slots: ({
                            /**
                             * Format: date-time
                             * @description Members only: until when withdrawing is free; null when no cutoff applies.
                             */
                            cancel_free_until?: string | null;
                            /** @description Members only: whether the viewer's package includes this class, regardless of visits left. */
                            covered_by_package?: boolean;
                            /**
                             * Format: uuid
                             * @description ADR-230: the day WOD the class's WOD comes from.
                             */
                            day_workout_id?: string | null;
                            /** @description Members only: people the viewer follows who share their bookings and hold a place in this class (the «Φίλοι» chip). */
                            friends_going?: {
                                avatar_url?: string | null;
                                /** Format: uuid */
                                id: string;
                                nickname?: string | null;
                            }[];
                            /** @description ADR-202: the room or area of the branch the class is held in. */
                            space?: {
                                /** Format: uuid */
                                id: string;
                                name: string;
                            } | null;
                            /** Format: uuid */
                            space_id?: string | null;
                            /** @description Staff only: another class is in the same space at an overlapping time (a warning, not a block). */
                            space_overlap?: boolean;
                            /** @description Staff only: the space was made unavailable for this class's time after it was planned. */
                            space_unavailable?: boolean;
                            workout?: ({
                                /** @description What the workout trains, read from its movements. */
                                focus?: ("strength" | "endurance" | "gymnastics" | "olympic_lifting" | "mobility" | "legs" | "core" | "upper_body")[];
                            } & {
                                [key: string]: unknown;
                            }) | null;
                            /**
                             * @description ADR-230: day = inherited from the day's WOD, class = set on the class.
                             * @enum {string|null}
                             */
                            workout_source?: "day" | "class" | null;
                        } & {
                            [key: string]: unknown;
                        })[];
                        /** Format: date */
                        start_date: string;
                    };
                };
            };
        };
    };
