    "PaleeWeb.TrainingDepthController.client": {
        parameters: {
            query?: {
                range?: "4w" | "12w" | "6m" | "1y" | "all";
            };
            header?: never;
            path: {
                user_id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Client training depth */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** DepthCoverage */
                        coverage: {
                            /**
                             * DepthBalance
                             * @description Exercise sets by primary muscles; a ratio only once both sides have sets and reach 4 together
                             */
                            balance: {
                                ham: number;
                                pull: number;
                                push: number;
                                push_pull_ratio: number | null;
                                quad: number;
                                quad_ham_ratio: number | null;
                            };
                            /** DepthExerciseCounts */
                            exercises: {
                                recognized: number;
                                unrecognized: number;
                            };
                            felt_entries: number;
                            /** @description Up to three major groups at level none or low, lowest first */
                            least: {
                                /** @description Taxonomy group id */
                                id: string;
                                /** @enum {string} */
                                level: "none" | "low" | "medium" | "high";
                                per_week: number;
                                /** @description Weighted sets in the range */
                                sets: number;
                            }[];
                            /** @description Up to three major groups with the most weighted sets */
                            most: {
                                /** @description Taxonomy group id */
                                id: string;
                                /** @enum {string} */
                                level: "none" | "low" | "medium" | "high";
                                per_week: number;
                                /** @description Weighted sets in the range */
                                sets: number;
                            }[];
                            /** @description Workouts done in the range */
                            sessions: number;
                            /** DepthCoverageThresholds */
                            thresholds: {
                                high: number;
                                medium: number;
                            };
                        };
                        /** Format: date */
                        from: string;
                        /**
                         * DepthLoad
                         * @description Session RPE (effort × minutes) as of today: an indicator against the athlete's own usual week, never advice
                         */
                        load: {
                            /** @description Load of the last 7 days */
                            acute: number;
                            /** @enum {string|null} */
                            band: "below" | "steady" | "above" | "well_above" | null;
                            /** DepthLoadBands */
                            bands: {
                                above_to: number;
                                below: number;
                                steady_to: number;
                            };
                            /** @description Weekly average of the last 28 days */
                            chronic: number;
                            /** @description Last 28 days, with effort and time */
                            rated_sessions: number;
                            ratio: number | null;
                            sufficient: boolean;
                            /** @description Last 28 days, without effort or time (not counted) */
                            unrated_sessions: number;
                            weeks: {
                                load: number;
                                sessions: number;
                                /** Format: date */
                                week_start: string;
                            }[];
                        };
                        /** DepthQualities */
                        qualities: {
                            felt_entries: number;
                            /** @description All ten qualities, canonical order */
                            qualities: {
                                felt: number;
                                id: string;
                                /** @description Share of the most-trained quality, 0..1 */
                                score: number;
                                sets: number;
                            }[];
                            /** @description Workouts with a recognised exercise */
                            sessions: number;
                        };
                        /** @enum {string} */
                        range: "4w" | "12w" | "6m" | "1y" | "all";
                        /** Format: date */
                        to: string;
                        weeks: number;
                    };
                };
            };
            /** @description Error */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: string;
                    };
                };
            };
            /** @description Error */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: string;
                    };
                };
            };
        };
    };
